  },
  "devDependencies": {
    "@types/express": "5.0.3",
    "@types/node": "24.19.1"
  },
  "nodemonConfig": {
    "ignore": [
      ".git",
      "**/node_modules/**",
      "**/build/**"
    ],
    "watch": [
      "app.ts"
    ],
    "verbose": true,
    "ext": "js,jsx,json,ts,tsx"
  }
}

